; sound.asm -- appendix C: a tone's period and its volume, bit by bit
; generated by genC.py
        INCLUDE "msx.inc"
        OUTPUT "sound.rom"
        ORG $4000
        CART_HEADER init

; Channel A's tone at each period of TONES, then at $100 with each
; volume of VOLUMES: 25 frames each. measC.py records the sound, and
; notes the time at each label s<case>.

init:   di
        ld sp,$F370
        ld a,7
        out (PSG_ADDR),a
        ld a,$BE
        out (PSG_WRITE),a       ; register 7 = $BE: tone A alone
        ld a,8
        out (PSG_ADDR),a
        ld a,$0F
        out (PSG_WRITE),a       ; register 8 = $0F: the loudest
        ld a,9
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 9 = $00
        ld a,10
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 10 = $00
; t010
        ld a,0
        out (PSG_ADDR),a
        ld a,$10
        out (PSG_WRITE),a       ; register 0 = $10
        ld a,1
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 1 = $00: a period of $010
st010:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt010_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt010_1
        dec e
        jr nz,frt010_1
; t020
        ld a,0
        out (PSG_ADDR),a
        ld a,$20
        out (PSG_WRITE),a       ; register 0 = $20
        ld a,1
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 1 = $00: a period of $020
st020:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt020_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt020_1
        dec e
        jr nz,frt020_1
; t040
        ld a,0
        out (PSG_ADDR),a
        ld a,$40
        out (PSG_WRITE),a       ; register 0 = $40
        ld a,1
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 1 = $00: a period of $040
st040:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt040_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt040_1
        dec e
        jr nz,frt040_1
; t080
        ld a,0
        out (PSG_ADDR),a
        ld a,$80
        out (PSG_WRITE),a       ; register 0 = $80
        ld a,1
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 1 = $00: a period of $080
st080:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt080_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt080_1
        dec e
        jr nz,frt080_1
; t100
        ld a,0
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 0 = $00
        ld a,1
        out (PSG_ADDR),a
        ld a,$01
        out (PSG_WRITE),a       ; register 1 = $01: a period of $100
st100:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt100_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt100_1
        dec e
        jr nz,frt100_1
; t200
        ld a,0
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 0 = $00
        ld a,1
        out (PSG_ADDR),a
        ld a,$02
        out (PSG_WRITE),a       ; register 1 = $02: a period of $200
st200:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt200_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt200_1
        dec e
        jr nz,frt200_1
; t400
        ld a,0
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 0 = $00
        ld a,1
        out (PSG_ADDR),a
        ld a,$04
        out (PSG_WRITE),a       ; register 1 = $04: a period of $400
st400:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt400_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt400_1
        dec e
        jr nz,frt400_1
; t800
        ld a,0
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 0 = $00
        ld a,1
        out (PSG_ADDR),a
        ld a,$08
        out (PSG_WRITE),a       ; register 1 = $08: a period of $800
st800:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frt800_1: in a,(VDP_CTRL)
        rlca
        jr nc,frt800_1
        dec e
        jr nz,frt800_1
; tFFF
        ld a,0
        out (PSG_ADDR),a
        ld a,$FF
        out (PSG_WRITE),a       ; register 0 = $FF
        ld a,1
        out (PSG_ADDR),a
        ld a,$0F
        out (PSG_WRITE),a       ; register 1 = $0F: a period of $FFF
stFFF:  nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frtFFF_1: in a,(VDP_CTRL)
        rlca
        jr nc,frtFFF_1
        dec e
        jr nz,frtFFF_1
; tv
        ld a,0
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 0 = $00
        ld a,1
        out (PSG_ADDR),a
        ld a,$01
        out (PSG_WRITE),a       ; register 1 = $01
stv:    nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frtv_1: in a,(VDP_CTRL)
        rlca
        jr nc,frtv_1
        dec e
        jr nz,frtv_1
; v1
        ld a,8
        out (PSG_ADDR),a
        ld a,$01
        out (PSG_WRITE),a       ; register 8 = $01: the volume
sv1:    nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frv1_1: in a,(VDP_CTRL)
        rlca
        jr nc,frv1_1
        dec e
        jr nz,frv1_1
; v2
        ld a,8
        out (PSG_ADDR),a
        ld a,$02
        out (PSG_WRITE),a       ; register 8 = $02: the volume
sv2:    nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frv2_1: in a,(VDP_CTRL)
        rlca
        jr nc,frv2_1
        dec e
        jr nz,frv2_1
; v4
        ld a,8
        out (PSG_ADDR),a
        ld a,$04
        out (PSG_WRITE),a       ; register 8 = $04: the volume
sv4:    nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frv4_1: in a,(VDP_CTRL)
        rlca
        jr nc,frv4_1
        dec e
        jr nz,frv4_1
; v8
        ld a,8
        out (PSG_ADDR),a
        ld a,$08
        out (PSG_WRITE),a       ; register 8 = $08: the volume
sv8:    nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frv8_1: in a,(VDP_CTRL)
        rlca
        jr nc,frv8_1
        dec e
        jr nz,frv8_1
; v15
        ld a,8
        out (PSG_ADDR),a
        ld a,$0F
        out (PSG_WRITE),a       ; register 8 = $0F: the volume
sv15:   nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
frv15_1: in a,(VDP_CTRL)
        rlca
        jr nc,frv15_1
        dec e
        jr nz,frv15_1
; off
        ld a,8
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 8 = $00: silence
soff:   nop                     ; measC.py notes the time
        ld e,25
        in a,(VDP_CTRL)
froff_1: in a,(VDP_CTRL)
        rlca
        jr nc,froff_1
        dec e
        jr nz,froff_1
done:   jr done

        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
